program.source:
let w = window_rect("AutoFlow Manual Acceptance Harness");
if w.found {
    let first = find_image("manual-vision-target.png", w.x, w.y, w.width, w.height, 0.95);
    if first.found {
        stop_with_message("MANUAL_TEST_IMAGE_UNEXPECTED_HIT", "MANUAL_TEST_IMAGE_INITIAL_LOOKUP_HIT");
    } else {
        let waited = wait_image("manual-vision-target.png", w.x, w.y, w.width, w.height, 0.95, 1500, 150);
        if waited.found {
            stop_with_message("MANUAL_TEST_IMAGE_HIT_DURING_WAIT", "MANUAL_TEST_IMAGE_WAIT_LOOKUP_HIT");
        } else {
            stop_with_message("MANUAL_TEST_IMAGE_MISS_TIMEOUT", "MANUAL_TEST_IMAGE_MISS_THEN_TIMEOUT");
        }
    }
}
